"""Algorithm-neutral contracts shared by GRPO, DiLoCo, and future SAO runs."""

from __future__ import annotations

import math
import re
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

_SHA256 = re.compile(r"[0-9a-f]{64}\Z")
_IDENTIFIER = re.compile(r"[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,255}\Z")
_ALGORITHMS = frozenset({"grpo", "sao", "ppo"})
_TRAINER_EXCHANGE_MODES = frozenset({"dense", "pulseloco"})
_INFERENCE_PUBLICATION_MODES = frozenset({"full", "pulsesync"})
# A trajectory generated by a merged cut the syncer broadcast to a
# receive-only subscriber (relay mode, ``yeto.rl.engine.external_policy``),
# not by one of the training island's own publications.
EXTERNAL_MERGED_CUT = "external-merged-cut"


def _require_sha256(name: str, value: str) -> None:
    if not _SHA256.fullmatch(value):
        raise ValueError(f"{name} must be a lowercase SHA256")


def _require_identifier(name: str, value: str) -> None:
    if not _IDENTIFIER.fullmatch(value):
        raise ValueError(f"{name} is not a closed identifier")


def _require_nonnegative_int(name: str, value: int) -> None:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{name} must be a non-negative integer")


def _require_algorithm(value: str) -> None:
    if value not in _ALGORITHMS:
        raise ValueError(f"unsupported local RL algorithm: {value!r}")


@dataclass(frozen=True)
class TrajectoryEnvelope:
    """One exactly-once trajectory and the policy/reward evidence that owns it."""

    trajectory_id: str
    task_id: str
    prompt_group_id: str
    sample_index: int
    # None (both) only for an external merged cut (``behavior_policy_kind``)
    behavior_policy_version: int | None
    behavior_policy_hash: str | None
    token_ids: tuple[int, ...]
    response_token_count: int
    behavior_logprobs_hash: str | None
    reward: float
    reward_contract_hash: str
    cleanup_evidence_hash: str
    evidence_kind: str | None = None
    active_token_count: int | None = None
    loss_mask_hash: str | None = None
    active_token_ids_hash: str | None = None
    active_behavior_logprobs_hash: str | None = None
    compaction_trajectory_id: str | None = None
    compaction_segment_index: int | None = None
    compaction_segment_type: str | None = None
    compaction_context_budget: int | None = None
    # A segment of a trial split by context compaction (``metadata.compaction``,
    # :func:`validate_compaction_group`): the trial's segment count. Set only on
    # such segments, which then carry no ``compaction_segment_type`` (a segment
    # holds both execution turns and its closing summary turn).
    compaction_num_segments: int | None = None
    # (trajectory evidence schema 5) the behavior policy is an external
    # merged cut, named by its merged version and cut digest; the local
    # publication fields above are then None.
    behavior_policy_kind: str | None = None
    behavior_merged_version: int | None = None
    behavior_cut_digest: str | None = None

    def __post_init__(self) -> None:
        for name in ("trajectory_id", "task_id", "prompt_group_id"):
            _require_identifier(name, getattr(self, name))
        _require_nonnegative_int("sample_index", self.sample_index)
        external = (
            self.behavior_policy_kind,
            self.behavior_merged_version,
            self.behavior_cut_digest,
        )
        if any(value is not None for value in external):
            if self.behavior_policy_kind != EXTERNAL_MERGED_CUT:
                raise ValueError("trajectory behavior policy kind is unsupported")
            _require_nonnegative_int(
                "behavior_merged_version", self.behavior_merged_version  # type: ignore[arg-type]
            )
            if not isinstance(self.behavior_cut_digest, str):
                raise ValueError("behavior_cut_digest must be a lowercase SHA256")
            _require_sha256("behavior_cut_digest", self.behavior_cut_digest)
            if (
                self.behavior_policy_version is not None
                or self.behavior_policy_hash is not None
            ):
                raise ValueError(
                    "an external merged cut does not name a local publication"
                )
        else:
            _require_nonnegative_int(
                "behavior_policy_version", self.behavior_policy_version  # type: ignore[arg-type]
            )
            if not isinstance(self.behavior_policy_hash, str):
                raise ValueError("behavior_policy_hash must be a lowercase SHA256")
            _require_sha256("behavior_policy_hash", self.behavior_policy_hash)
        for name in (
            "reward_contract_hash",
            "cleanup_evidence_hash",
        ):
            _require_sha256(name, getattr(self, name))
        if self.behavior_logprobs_hash is not None:
            _require_sha256("behavior_logprobs_hash", self.behavior_logprobs_hash)
        if not self.token_ids or any(
            isinstance(token, bool) or not isinstance(token, int) or token < 0
            for token in self.token_ids
        ):
            raise ValueError("trajectory token IDs must be non-empty and non-negative")
        _require_nonnegative_int("response_token_count", self.response_token_count)
        if not 1 <= self.response_token_count <= len(self.token_ids):
            raise ValueError(
                "trajectory response-token count must cover a non-empty token suffix"
            )
        if not math.isfinite(self.reward):
            raise ValueError("trajectory reward must be finite")
        if self.evidence_kind is not None:
            _require_identifier("evidence_kind", self.evidence_kind)
        active_fields = (
            self.active_token_count,
            self.loss_mask_hash,
            self.active_token_ids_hash,
        )
        if any(value is not None for value in active_fields):
            if any(value is None for value in active_fields):
                raise ValueError("trajectory active-token evidence is incomplete")
            _require_nonnegative_int(
                "active_token_count", self.active_token_count  # type: ignore[arg-type]
            )
            if self.active_token_count > self.response_token_count:  # type: ignore[operator]
                raise ValueError(
                    "trajectory active-token count exceeds its response length"
                )
            _require_sha256("loss_mask_hash", self.loss_mask_hash)  # type: ignore[arg-type]
            _require_sha256(
                "active_token_ids_hash", self.active_token_ids_hash  # type: ignore[arg-type]
            )
            if self.active_behavior_logprobs_hash is not None:
                _require_sha256(
                    "active_behavior_logprobs_hash",
                    self.active_behavior_logprobs_hash,
                )
        elif self.active_behavior_logprobs_hash is not None:
            raise ValueError(
                "trajectory active log probabilities lack active-token evidence"
            )

        if self.compaction_num_segments is not None:
            self._check_segmented_trial()
            return
        compaction_fields = (
            self.compaction_trajectory_id,
            self.compaction_segment_index,
            self.compaction_segment_type,
            self.compaction_context_budget,
        )
        if any(value is not None for value in compaction_fields):
            if any(value is None for value in compaction_fields):
                raise ValueError("trajectory compaction identity is incomplete")
            _require_identifier(
                "compaction_trajectory_id",
                self.compaction_trajectory_id,  # type: ignore[arg-type]
            )
            _require_nonnegative_int(
                "compaction_segment_index",
                self.compaction_segment_index,  # type: ignore[arg-type]
            )
            if self.compaction_segment_type not in {"execution", "summary"}:
                raise ValueError("trajectory compaction segment type is invalid")
            if (
                type(self.compaction_context_budget) is not int
                or self.compaction_context_budget < 1
            ):
                raise ValueError("trajectory compaction context budget is invalid")

    def _check_segmented_trial(self) -> None:
        if self.compaction_segment_type is not None:
            raise ValueError("a compaction segment of a trial has no segment type")
        if (
            type(self.compaction_num_segments) is not int
            or self.compaction_num_segments < 1
        ):
            raise ValueError("trajectory compaction segment count is invalid")
        if not isinstance(self.compaction_trajectory_id, str):
            raise ValueError("trajectory compaction identity is incomplete")
        _require_identifier("compaction_trajectory_id", self.compaction_trajectory_id)
        _require_nonnegative_int(
            "compaction_segment_index", self.compaction_segment_index  # type: ignore[arg-type]
        )
        if self.compaction_segment_index >= self.compaction_num_segments:  # type: ignore[operator]
            raise ValueError("trajectory compaction segment index exceeds its count")
        if (
            type(self.compaction_context_budget) is not int
            or self.compaction_context_budget < 1
        ):
            raise ValueError("trajectory compaction context budget is invalid")


# ``metadata.compaction`` of one segment sample (compaction-1118 contract 2)
COMPACTION_METADATA_KEY = "compaction"
COMPACTION_METADATA_SCHEMA = 1
_COMPACTION_INT_FIELDS = ("segment_index", "num_segments", "context_budget",
                          "kept_steps", "segment_tokens", "tokens_after")
_TRAINABLE_STATUSES = frozenset({"completed", "truncated"})


@dataclass(frozen=True)
class CompactionTrial:
    """One trial of a buffer group: its sample ``index``, the positions of its
    samples in the group (in segment order), and, when context compaction split
    it, its ``trajectory_id`` (None: one uncompacted sample)."""

    index: int
    positions: tuple[int, ...]
    trajectory_id: str | None = None

    @property
    def num_segments(self) -> int:
        return len(self.positions)


def _field(sample: Any, name: str) -> Any:
    if isinstance(sample, Mapping):
        return sample.get(name)
    return getattr(sample, name, None)


def _status_name(sample: Any) -> Any:
    status = _field(sample, "status")
    return getattr(status, "value", status)


def compaction_metadata(sample: Any) -> Mapping[str, Any] | None:
    """``metadata.compaction`` of a segment sample (a mapping or a Miles Sample);
    None for a sample of an uncompacted trial."""
    metadata = _field(sample, "metadata")
    if not isinstance(metadata, Mapping):
        return None
    value = metadata.get(COMPACTION_METADATA_KEY)
    if value is None:
        return None
    if not isinstance(value, Mapping):
        raise ValueError("metadata.compaction is not an object")
    return value


def validate_compaction_group(samples: Sequence[Any]) -> tuple[CompactionTrial, ...]:
    """Check one buffer group whose trials context compaction may have split
    into segments, and return its trials in first-seen order.

    Samples are buffer mappings or Miles Samples. All share one integer
    ``group_index``; a trial is the samples with one integer ``index`` (they
    need not be adjacent; ``CompactionTrial.positions`` lists them in segment
    order). A trial without ``metadata.compaction`` is exactly one sample. A
    compacted trial's samples all carry ``metadata.compaction`` with schema 1,
    one non-empty ``trajectory_id`` (no sample of another index names it),
    ``segment_index`` 0..n-1 (each once), ``num_segments`` n, one positive
    ``context_budget``, a boolean ``summary_ok`` and non-negative
    ``kept_steps`` / ``segment_tokens`` / ``tokens_after``; they share one
    finite ``reward``, and only the last segment may be ``truncated`` (the
    earlier ones are ``completed``). A ``rollout_id`` (Miles' rollout key),
    when a trial's samples carry one, is the same on all of them and differs
    between trials. Raises ``ValueError`` otherwise.

    Callers count trials (``len(result)``), not samples, against
    ``n_samples_per_prompt``. This is not the legacy PPO check
    (``yeto.rl.compaction.validate_compaction_segments``: flat
    ``compaction_*`` keys, alternating execution/summary segments).
    """
    if not samples:
        raise ValueError("compaction group is empty")
    group_indexes = {_field(sample, "group_index") for sample in samples}
    if len(group_indexes) != 1:
        raise ValueError("compaction group mixes group identities")
    _require_nonnegative_int("sample.group_index", next(iter(group_indexes)))
    by_index: dict[int, list[int]] = {}
    for position, sample in enumerate(samples):
        index = _field(sample, "index")
        _require_nonnegative_int("sample.index", index)
        by_index.setdefault(index, []).append(position)
    spans: dict[Any, set[int]] = {}
    for sample in samples:
        meta = compaction_metadata(sample)
        if meta is not None and isinstance(meta.get("trajectory_id"), str):
            spans.setdefault(meta["trajectory_id"], set()).add(_field(sample, "index"))
    for trajectory_id, indexes in spans.items():
        if len(indexes) > 1:
            raise ValueError(
                f"compaction trajectory {trajectory_id!r} spans sample indexes {sorted(indexes)} "
                "(the segments of one trial share its index)")
    trials: list[CompactionTrial] = []
    seen_rollouts: dict[Any, int] = {}
    for index, positions in by_index.items():
        trajectory_id, ordered = _check_trial_segments(index, samples, positions)
        # Miles keys a rollout by ``rollout_id`` (else ``index``): when set, one per trial
        rollout_ids = {_field(samples[position], "rollout_id") for position in positions}
        if rollout_ids != {None}:
            if len(rollout_ids) != 1:
                raise ValueError(f"trial {index}: its samples carry rollout ids {sorted(map(str, rollout_ids))}")
            rollout_id = next(iter(rollout_ids))
            if rollout_id in seen_rollouts:
                raise ValueError(f"trial {index}: rollout id {rollout_id!r} is also trial "
                                 f"{seen_rollouts[rollout_id]}")
            seen_rollouts[rollout_id] = index
        trials.append(CompactionTrial(index, ordered, trajectory_id))
    return tuple(trials)


def _check_trial_segments(
    index: int, samples: Sequence[Any], positions: Sequence[int]
) -> tuple[str | None, tuple[int, ...]]:
    """(trajectory id or None, the trial's positions in segment order)."""
    metas = [compaction_metadata(samples[position]) for position in positions]
    if all(meta is None for meta in metas):
        if len(positions) != 1:
            raise ValueError(f"trial {index}: {len(positions)} samples share its index "
                             "without compaction metadata")
        return None, tuple(positions)
    if any(meta is None for meta in metas):
        raise ValueError(f"trial {index}: some segments lack compaction metadata")
    where = f"trial {index}"
    for meta in metas:
        assert meta is not None
        if meta.get("schema") != COMPACTION_METADATA_SCHEMA:
            raise ValueError(f"{where}: compaction metadata has an unsupported schema")
        for name in _COMPACTION_INT_FIELDS:
            value = meta.get(name)
            if type(value) is not int or value < 0:
                raise ValueError(f"{where}: compaction {name} must be a non-negative integer")
        if type(meta.get("summary_ok")) is not bool:
            raise ValueError(f"{where}: compaction summary_ok must be a boolean")
    order = sorted(range(len(positions)), key=lambda k: metas[k]["segment_index"])  # type: ignore[index]
    segments = [samples[positions[k]] for k in order]
    metas = [metas[k] for k in order]
    first = metas[0]
    assert first is not None
    trajectory_id = first.get("trajectory_id")
    if not isinstance(trajectory_id, str) or not trajectory_id:
        raise ValueError(f"{where}: compaction metadata has no trajectory id")
    rewards = []
    for ordinal, (sample, meta) in enumerate(zip(segments, metas)):
        assert meta is not None
        if meta.get("trajectory_id") != trajectory_id:
            raise ValueError(f"{where}: segments mix compaction trajectory ids")
        if meta["segment_index"] != ordinal:
            raise ValueError(f"{where}: compaction segment indexes are not 0..n-1")
        if meta["num_segments"] != len(segments):
            raise ValueError(f"{where}: num_segments {meta['num_segments']} != "
                             f"{len(segments)} segments in the group")
        if meta["context_budget"] < 1 or meta["context_budget"] != first.get("context_budget"):
            raise ValueError(f"{where}: compaction context budget is invalid or changed")
        status = _status_name(sample)
        allowed = _TRAINABLE_STATUSES if ordinal == len(segments) - 1 else {"completed"}
        if status not in allowed:
            raise ValueError(f"{where}: segment {ordinal} has status {status!r}")
        reward = _field(sample, "reward")
        if (isinstance(reward, bool) or not isinstance(reward, (int, float))
                or not math.isfinite(float(reward))):
            raise ValueError(f"{where}: segment {ordinal} has no finite reward")
        rewards.append(float(reward))
    if len(set(rewards)) != 1:
        raise ValueError(f"{where}: segments do not share one reward")
    return trajectory_id, tuple(positions[k] for k in order)


@dataclass(frozen=True)
class LocalStepReceipt:
    """Evidence emitted after one learner completes a safe local-step boundary."""

    algorithm: str
    learner_id: int
    learner_generation: int
    base_policy_version: int
    base_policy_hash: str
    input_batch_hash: str
    trajectory_ids: tuple[str, ...]
    trained_tokens: int
    optimizer_steps: int
    optimizer_step_succeeded: bool
    parameter_layout_hash: str

    def __post_init__(self) -> None:
        _require_algorithm(self.algorithm)
        for name in (
            "learner_id",
            "learner_generation",
            "base_policy_version",
            "trained_tokens",
            "optimizer_steps",
        ):
            _require_nonnegative_int(name, getattr(self, name))
        for name in (
            "base_policy_hash",
            "input_batch_hash",
            "parameter_layout_hash",
        ):
            _require_sha256(name, getattr(self, name))
        if not self.trajectory_ids:
            raise ValueError("local-step receipt must bind at least one trajectory")
        if len(set(self.trajectory_ids)) != len(self.trajectory_ids):
            raise ValueError("local-step receipt contains duplicate trajectories")
        for trajectory_id in self.trajectory_ids:
            _require_identifier("trajectory_id", trajectory_id)
        if not isinstance(self.optimizer_step_succeeded, bool):
            raise TypeError("optimizer_step_succeeded must be a boolean")
        if self.optimizer_step_succeeded:
            if self.optimizer_steps < 1 or self.trained_tokens < 1:
                raise ValueError(
                    "a successful local step must train tokens and advance the optimizer"
                )
        elif self.optimizer_steps != 0:
            raise ValueError("a failed local step cannot claim optimizer advancement")


@dataclass(frozen=True)
class TrainerUpdateManifest:
    """Content identity for either a dense or PULSELoCo trainer update."""

    exchange_mode: str
    learner_id: int
    learner_generation: int
    base_policy_version: int
    target_policy_version: int
    parameter_layout_hash: str
    payload_hash: str
    payload_bytes: int
    fragment_count: int
    complete: bool
    error_feedback_version: int | None = None
    threshold_contract_hash: str | None = None

    def __post_init__(self) -> None:
        if self.exchange_mode not in _TRAINER_EXCHANGE_MODES:
            raise ValueError(f"unsupported trainer exchange: {self.exchange_mode!r}")
        for name in (
            "learner_id",
            "learner_generation",
            "base_policy_version",
            "target_policy_version",
            "payload_bytes",
            "fragment_count",
        ):
            _require_nonnegative_int(name, getattr(self, name))
        for name in ("parameter_layout_hash", "payload_hash"):
            _require_sha256(name, getattr(self, name))
        if not isinstance(self.complete, bool):
            raise TypeError("trainer update completeness must be a boolean")
        if self.target_policy_version <= self.base_policy_version:
            raise ValueError("trainer update target must follow its base")
        if self.payload_bytes < 1 or self.fragment_count < 1 or not self.complete:
            raise ValueError("trainer update must bind one complete non-empty payload")
        if self.exchange_mode == "dense":
            if (
                self.error_feedback_version is not None
                or self.threshold_contract_hash is not None
            ):
                raise ValueError("dense trainer updates cannot carry PULSE state")
        else:
            if self.error_feedback_version is None:
                raise ValueError("PULSELoCo update must bind error-feedback state")
            _require_nonnegative_int(
                "error_feedback_version", self.error_feedback_version
            )
            if self.threshold_contract_hash is None:
                raise ValueError("PULSELoCo update must bind a threshold contract")
            _require_sha256("threshold_contract_hash", self.threshold_contract_hash)


@dataclass(frozen=True)
class InferencePublicationManifest:
    """Atomic full-checkpoint or PULSESync publication for rollout workers."""

    publication_mode: str
    base_policy_version: int | None
    target_policy_version: int
    target_policy_hash: str
    target_manifest_hash: str
    payload_hash: str
    payload_bytes: int
    complete: bool

    def __post_init__(self) -> None:
        if self.publication_mode not in _INFERENCE_PUBLICATION_MODES:
            raise ValueError(
                f"unsupported inference publication: {self.publication_mode!r}"
            )
        _require_nonnegative_int("target_policy_version", self.target_policy_version)
        _require_nonnegative_int("payload_bytes", self.payload_bytes)
        for name in (
            "target_policy_hash",
            "target_manifest_hash",
            "payload_hash",
        ):
            _require_sha256(name, getattr(self, name))
        if not isinstance(self.complete, bool):
            raise TypeError("inference publication completeness must be a boolean")
        if self.payload_bytes < 1 or not self.complete:
            raise ValueError("inference publication must be complete and non-empty")
        if self.publication_mode == "full":
            if self.base_policy_version is not None:
                raise ValueError("full publication cannot depend on a base policy")
        else:
            if self.base_policy_version is None:
                raise ValueError("PULSESync publication must bind an exact base")
            _require_nonnegative_int("base_policy_version", self.base_policy_version)
            if self.target_policy_version <= self.base_policy_version:
                raise ValueError("PULSESync target must follow its exact base")
